export const sandmProducts: Product[] = sandmProductsRaw.map(p => {
  const cat = sandmCategories.find(c => c.slug === p.categorySlug) || sandmCategories[0];
  return {
    id: p.id,
    name: p.name,
    slug: p.slug,
    category: cat as unknown as Product['category'],
    price: p.price,
    originalPrice: p.originalPrice ?? undefined,
    stock: p.stock,
    badge: p.badge || undefined,
    fragrance: p.fragrance || undefined,
    colour: p.colour || undefined,
    size: p.size || undefined,
    description: p.description,
    shortDescription: p.shortDescription || undefined,
    highlights: (p as any).highlights,
    rating: (p as any).rating,
    reviewsCount: (p as any).reviewsCount,
    specifications: p.specifications,
    variations: p.variations,
    image: p.image as unknown as Media,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  } as unknown as Product;
});

